class Solution { public: vector<int> peopleIndexes(vector<vector<string>>& favoriteCompanies){vector<unordered_set<string>> sets;for(auto& companies:favoriteCompanies)sets.emplace_back(companies.begin(),companies.end());vector<int> answer;for(int i=0;i<(int)sets.size();++i){bool subset=false;for(int j=0;j<(int)sets.size()&&!subset;++j)if(i!=j&&sets[j].size()>=sets[i].size()){subset=true;for(auto& company:sets[i])if(!sets[j].count(company)){subset=false;break;}}if(!subset)answer.push_back(i);}return answer;} };
